-- East Sound Technologies — one-shot database setup.
--
-- Paste this whole file into Supabase → SQL Editor → New query → Run.
-- It runs migrations 0001 → 0003 in one transaction: either everything
-- is created, or nothing is, so a retry is always safe.
--
-- Generated by: npm run setup:sql   (do not edit by hand)

begin;

-- ==========================================================================
-- 1. 0001_rbac_schema.sql
-- Core schema: organisations, profiles, roles, RLS policies
-- ==========================================================================

-- East Sound Technologies — core schema with strict role isolation (RLS).
-- Isolation layer 3: even a hand-crafted API call with a valid JWT can only
-- read rows that belong to the caller's role and organisation.

create type public.app_role as enum ('cmo', 'label', 'artist', 'broadcaster', 'venue');

create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  kind public.app_role not null,
  created_at timestamptz not null default now()
);

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  role public.app_role not null,
  org_id uuid references public.organizations (id),
  display_name text,
  -- CMO accounts see everything, so they start unapproved and are activated by staff.
  approved boolean not null default true,
  created_at timestamptz not null default now()
);

-- ── Helpers (security definer so policies don't recurse through profiles RLS) ──
create or replace function public.my_role() returns public.app_role
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and approved
$$;

create or replace function public.my_org() returns uuid
language sql stable security definer set search_path = public as $$
  select org_id from public.profiles where id = auth.uid()
$$;

-- ── New-user trigger: role comes from sign-up metadata, validated here ──
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  requested text := new.raw_user_meta_data ->> 'requested_role';
  r public.app_role;
  org uuid;
begin
  if requested not in ('cmo', 'label', 'artist', 'broadcaster', 'venue') then
    raise exception 'invalid role %', requested;
  end if;
  r := requested::public.app_role;
  if r <> 'artist' then
    insert into public.organizations (name, kind)
    values (coalesce(new.raw_user_meta_data ->> 'display_name', new.email), r)
    returning id into org;
  end if;
  insert into public.profiles (id, role, org_id, display_name, approved)
  values (new.id, r, org, new.raw_user_meta_data ->> 'display_name', r <> 'cmo');
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Users may edit their display name, never their role / org / approval.
create or replace function public.lock_profile_fields() returns trigger
language plpgsql as $$
begin
  if new.role <> old.role or new.org_id is distinct from old.org_id or new.approved <> old.approved then
    if coalesce(auth.role(), '') <> 'service_role' and current_user not in ('postgres', 'supabase_admin') then
      raise exception 'role, organisation and approval can only be changed by East Sound staff';
    end if;
  end if;
  return new;
end $$;
create trigger profiles_lock before update on public.profiles
  for each row execute function public.lock_profile_fields();

-- ── Domain tables ──
create table public.stations (
  id uuid primary key default gen_random_uuid(),
  broadcaster_org_id uuid not null references public.organizations (id),
  name text not null,
  frequency text,
  region text check (region in ('Central', 'Western', 'Eastern', 'Northern'))
);

create table public.venues (
  id uuid primary key default gen_random_uuid(),
  venue_org_id uuid not null references public.organizations (id),
  name text not null,
  uprs_licence text,
  licence_expires date
);

create table public.recordings (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  isrc text unique,
  upc text,
  label_org_id uuid references public.organizations (id),
  artist_profile_id uuid references public.profiles (id),
  fingerprint text,
  created_at timestamptz not null default now()
);

create table public.detections (
  id bigint generated always as identity primary key,
  recording_id uuid references public.recordings (id),
  station_id uuid references public.stations (id),
  venue_id uuid references public.venues (id),
  detected_at timestamptz not null,
  duration_sec int,
  confidence numeric(5, 2),
  evidence_path text, -- Supabase Storage key of the 10s clip
  check (num_nonnulls(station_id, venue_id) = 1)
);
create index on public.detections (recording_id, detected_at desc);
create index on public.detections (station_id, detected_at desc);

create table public.split_shares (
  id uuid primary key default gen_random_uuid(),
  recording_id uuid not null references public.recordings (id) on delete cascade,
  party_name text not null,
  party_profile_id uuid references public.profiles (id),
  share_pct numeric(5, 2) not null check (share_pct > 0 and share_pct <= 100)
);

create table public.disputes (
  id uuid primary key default gen_random_uuid(),
  recording_id uuid not null references public.recordings (id),
  claimant_a uuid references public.organizations (id),
  claimant_b uuid references public.organizations (id),
  status text not null default 'open',
  opened_at timestamptz not null default now()
);

create table public.alert_prefs (
  profile_id uuid primary key references public.profiles (id) on delete cascade,
  whatsapp_e164 text check (whatsapp_e164 ~ '^\+2567\d{8}$'),
  events jsonb not null default '{}'::jsonb
);

-- ── RLS ──
alter table public.organizations enable row level security;
alter table public.profiles enable row level security;
alter table public.stations enable row level security;
alter table public.venues enable row level security;
alter table public.recordings enable row level security;
alter table public.detections enable row level security;
alter table public.split_shares enable row level security;
alter table public.disputes enable row level security;
alter table public.alert_prefs enable row level security;

-- Profiles: own row only (CMO may read all for the registry).
create policy profiles_self on public.profiles for select using (id = auth.uid() or public.my_role() = 'cmo');
create policy profiles_self_update on public.profiles for update using (id = auth.uid());

create policy orgs_read on public.organizations for select using (id = public.my_org() or public.my_role() = 'cmo');

-- Stations / venues: owner org or CMO.
create policy stations_read on public.stations for select
  using (public.my_role() = 'cmo' or (public.my_role() = 'broadcaster' and broadcaster_org_id = public.my_org()));
create policy venues_read on public.venues for select
  using (public.my_role() = 'cmo' or (public.my_role() = 'venue' and venue_org_id = public.my_org()));

-- Recordings: CMO all; label its own; artist their own.
create policy recordings_read on public.recordings for select using (
  public.my_role() = 'cmo'
  or (public.my_role() = 'label' and label_org_id = public.my_org())
  or (public.my_role() = 'artist' and artist_profile_id = auth.uid())
);
create policy recordings_write_label on public.recordings for insert
  with check (public.my_role() = 'label' and label_org_id = public.my_org());
create policy recordings_update_label on public.recordings for update
  using (public.my_role() = 'label' and label_org_id = public.my_org());

-- Detections: visible only through something the caller owns.
create policy detections_read on public.detections for select using (
  public.my_role() = 'cmo'
  or exists (select 1 from public.recordings r where r.id = recording_id and (
       (public.my_role() = 'label' and r.label_org_id = public.my_org())
    or (public.my_role() = 'artist' and r.artist_profile_id = auth.uid())))
  or exists (select 1 from public.stations s where s.id = station_id
       and public.my_role() = 'broadcaster' and s.broadcaster_org_id = public.my_org())
  or exists (select 1 from public.venues v where v.id = venue_id
       and public.my_role() = 'venue' and v.venue_org_id = public.my_org())
);

create policy splits_read on public.split_shares for select using (
  public.my_role() = 'cmo'
  or party_profile_id = auth.uid()
  or exists (select 1 from public.recordings r where r.id = recording_id
       and public.my_role() = 'label' and r.label_org_id = public.my_org())
);

create policy disputes_read on public.disputes for select using (
  public.my_role() = 'cmo' or claimant_a = public.my_org() or claimant_b = public.my_org()
);
create policy disputes_cmo_update on public.disputes for update using (public.my_role() = 'cmo');

create policy alerts_self on public.alert_prefs for all
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());

-- ==========================================================================
-- 2. 0002_stream_ingest.sql
-- Stream ingest: stations, detections, evidence bucket
-- ==========================================================================

-- Stream-ingest support: monitored stations, richer detections, unmatched queue,
-- private evidence bucket. The ingest worker writes with the service-role key
-- (bypasses RLS); dashboards read through the RLS policies below.

-- Stations can now be monitored before the broadcaster signs up as a client.
alter table public.stations alter column broadcaster_org_id drop not null;
alter table public.stations
  add column if not exists slug text unique,
  add column if not exists stream_url text,
  add column if not exists stream_status text check (stream_status in ('starting', 'online', 'reconnecting', 'no_stream_url', 'disabled')),
  add column if not exists now_playing text,
  add column if not exists last_heartbeat timestamptz;

alter table public.detections
  add column if not exists ended_at timestamptz,
  add column if not exists match_score int,
  add column if not exists track_offset_sec numeric(8, 1),
  add column if not exists matched_title text,
  add column if not exists matched_artist text,
  add column if not exists source text not null default 'stream' check (source in ('stream', 'fm', 'venue', 'manual'));

-- A play can't end before it starts; detections are append-only facts.
alter table public.detections add constraint detections_time_order check (ended_at is null or ended_at >= detected_at);
create index if not exists detections_detected_at on public.detections (detected_at desc);

create table if not exists public.unmatched_clips (
  id bigint generated always as identity primary key,
  station_id uuid references public.stations (id),
  heard_at timestamptz not null,
  evidence_path text not null,
  rms numeric(5, 3),
  status text not null default 'open' check (status in ('open', 'matched', 'discarded')),
  matched_recording_id uuid references public.recordings (id),
  resolved_by uuid references public.profiles (id),
  resolved_at timestamptz
);
alter table public.unmatched_clips enable row level security;

-- Unmatched audio is CMO-only (it may contain anyone's music).
create policy unmatched_cmo_read on public.unmatched_clips for select using (public.my_role() = 'cmo');
create policy unmatched_cmo_update on public.unmatched_clips for update using (public.my_role() = 'cmo');

-- Monitored stations with no broadcaster client yet are visible to CMO only
-- (covered by the existing stations_read policy, which requires a matching org).

-- Private bucket for 10-second evidence clips. Dashboards get short-lived signed
-- URLs from a server route; nobody reads the bucket directly except CMO.
insert into storage.buckets (id, name, public) values ('evidence', 'evidence', false)
on conflict (id) do nothing;

create policy evidence_cmo_read on storage.objects for select
  using (bucket_id = 'evidence' and public.my_role() = 'cmo');

-- ==========================================================================
-- 3. 0003_dashboards_live.sql
-- Dashboards: aggregates, dispute queue, playout functions
-- ==========================================================================

-- Everything the five dashboards need to run on live data.
-- Aggregate functions are SECURITY INVOKER (the default): they run under the
-- caller's RLS, so a label's "top tracks" can only ever count the label's rows.
-- The two public_* functions are SECURITY DEFINER but return only
-- non-sensitive aggregates (title, artist, spin counts) — never evidence.

-- ── Catalogue detail ───────────────────────────────────────────────────────
alter table public.recordings
  add column if not exists artist_name text,
  add column if not exists release_date date,
  add column if not exists composer text,
  add column if not exists publisher text,
  add column if not exists duration_sec int;

create table if not exists public.artists (
  id uuid primary key default gen_random_uuid(),
  label_org_id uuid not null references public.organizations (id) on delete cascade,
  name text not null check (length(trim(name)) between 1 and 120),
  genre text,
  created_at timestamptz not null default now()
);
alter table public.recordings add column if not exists artist_id uuid references public.artists (id);
alter table public.artists enable row level security;
create policy artists_read on public.artists for select
  using (public.my_role() = 'cmo' or (public.my_role() = 'label' and label_org_id = public.my_org()));
create policy artists_label_write on public.artists for insert
  with check (public.my_role() = 'label' and label_org_id = public.my_org());
create policy artists_label_update on public.artists for update
  using (public.my_role() = 'label' and label_org_id = public.my_org())
  with check (label_org_id = public.my_org());
create policy artists_label_delete on public.artists for delete
  using (public.my_role() = 'label' and label_org_id = public.my_org());

-- Labels may fix their own ISRC/UPC, but can never move a recording to another org.
drop policy if exists recordings_update_label on public.recordings;
create policy recordings_update_label on public.recordings for update
  using (public.my_role() = 'label' and label_org_id = public.my_org())
  with check (label_org_id = public.my_org());

-- ── Disputes: more context, staff-auditable resolution ─────────────────────
alter table public.disputes
  add column if not exists share_a numeric(5, 2),
  add column if not exists share_b numeric(5, 2),
  add column if not exists resolved_at timestamptz,
  add column if not exists resolved_by uuid references public.profiles (id);
alter table public.disputes drop constraint if exists disputes_status_check;
alter table public.disputes add constraint disputes_status_check
  check (status in ('open', 'resolved_a', 'resolved_b', 'resolved_split', 'escalated'));

-- ── Broadcaster: ad bookings + aired spots ─────────────────────────────────
create table if not exists public.ad_bookings (
  id uuid primary key default gen_random_uuid(),
  station_id uuid not null references public.stations (id) on delete cascade,
  advertiser text not null,
  spot text not null,
  daypart text,
  booked int not null check (booked >= 0),
  period_start date not null,
  period_end date not null,
  check (period_end >= period_start)
);
create table if not exists public.ad_spots (
  id bigint generated always as identity primary key,
  station_id uuid not null references public.stations (id) on delete cascade,
  booking_id uuid references public.ad_bookings (id) on delete set null,
  aired_at timestamptz not null,
  duration_sec int not null check (duration_sec > 0)
);
create index if not exists ad_spots_station_time on public.ad_spots (station_id, aired_at desc);
alter table public.ad_bookings enable row level security;
alter table public.ad_spots enable row level security;
create policy ad_bookings_read on public.ad_bookings for select using (
  public.my_role() = 'cmo' or exists (select 1 from public.stations s where s.id = station_id
    and public.my_role() = 'broadcaster' and s.broadcaster_org_id = public.my_org()));
create policy ad_spots_read on public.ad_spots for select using (
  public.my_role() = 'cmo' or exists (select 1 from public.stations s where s.id = station_id
    and public.my_role() = 'broadcaster' and s.broadcaster_org_id = public.my_org()));

-- ── Venue: listener nodes + DJ sets ────────────────────────────────────────
create table if not exists public.venue_nodes (
  id uuid primary key default gen_random_uuid(),
  venue_id uuid not null references public.venues (id) on delete cascade,
  code text not null,
  location text not null,
  kind text check (kind in ('Bar', 'Club', 'Lounge', 'Rooftop', 'Other')),
  last_heartbeat timestamptz,
  unique (venue_id, code)
);
alter table public.detections add column if not exists node_id uuid references public.venue_nodes (id);
create table if not exists public.dj_sets (
  id uuid primary key default gen_random_uuid(),
  venue_id uuid not null references public.venues (id) on delete cascade,
  dj text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  check (ends_at > starts_at)
);
alter table public.venue_nodes enable row level security;
alter table public.dj_sets enable row level security;
create policy venue_nodes_read on public.venue_nodes for select using (
  public.my_role() = 'cmo' or exists (select 1 from public.venues v where v.id = venue_id
    and public.my_role() = 'venue' and v.venue_org_id = public.my_org()));
create policy dj_sets_read on public.dj_sets for select using (
  public.my_role() = 'cmo' or exists (select 1 from public.venues v where v.id = venue_id
    and public.my_role() = 'venue' and v.venue_org_id = public.my_org()));
create policy dj_sets_venue_write on public.dj_sets for insert with check (
  exists (select 1 from public.venues v where v.id = venue_id
    and public.my_role() = 'venue' and v.venue_org_id = public.my_org()));

-- ── Royalty statements (labels & artists) ──────────────────────────────────
create table if not exists public.royalty_statements (
  id uuid primary key default gen_random_uuid(),
  org_id uuid references public.organizations (id),
  profile_id uuid references public.profiles (id),
  period date not null, -- first day of the month
  amount_ugx bigint not null check (amount_ugx >= 0),
  status text not null default 'estimated' check (status in ('estimated', 'final', 'paid')),
  check (num_nonnulls(org_id, profile_id) = 1)
);
alter table public.royalty_statements enable row level security;
create policy royalties_read on public.royalty_statements for select using (
  public.my_role() = 'cmo' or org_id = public.my_org() or profile_id = auth.uid());

-- ── Evidence clips: readable exactly when the detection is readable ────────
-- The subquery runs under the caller's RLS on detections/unmatched_clips.
drop policy if exists evidence_cmo_read on storage.objects;
create policy evidence_read on storage.objects for select using (
  bucket_id = 'evidence' and (
    exists (select 1 from public.detections d where d.evidence_path = name)
    or exists (select 1 from public.unmatched_clips u where u.evidence_path = name)
  ));

-- ── Aggregates (SECURITY INVOKER → caller's RLS applies) ───────────────────
create or replace function public.recording_spins(p_days int default 30)
returns table (recording_id uuid, spins bigint, last_7 bigint, prev_7 bigint, stations bigint)
language sql stable set search_path = public as $$
  select d.recording_id,
         count(*) filter (where d.detected_at >= now() - make_interval(days => p_days)),
         count(*) filter (where d.detected_at >= now() - interval '7 days'),
         count(*) filter (where d.detected_at >= now() - interval '14 days' and d.detected_at < now() - interval '7 days'),
         count(distinct d.station_id) filter (where d.detected_at >= now() - make_interval(days => p_days))
  from public.detections d
  where d.recording_id is not null and d.detected_at >= now() - make_interval(days => greatest(p_days, 14))
  group by d.recording_id
$$;

create or replace function public.daily_spins(p_recording uuid, p_days int default 14)
returns table (day date, spins bigint)
language sql stable set search_path = public as $$
  select g.day::date, count(d.id)
  from generate_series((now() at time zone 'Africa/Kampala')::date - (p_days - 1), (now() at time zone 'Africa/Kampala')::date, interval '1 day') g(day)
  left join public.detections d
    on d.recording_id = p_recording and (d.detected_at at time zone 'Africa/Kampala')::date = g.day::date
  group by g.day order by g.day
$$;

create or replace function public.top_chart(p_days int default 7, p_region text default null, p_limit int default 100)
returns table (rank bigint, recording_id uuid, title text, artist text, owner text, spins bigint, stations bigint)
language sql stable set search_path = public as $$
  select row_number() over (order by count(*) desc, r.title), r.id, r.title, r.artist_name, o.name,
         count(*), count(distinct d.station_id)
  from public.detections d
  join public.recordings r on r.id = d.recording_id
  left join public.organizations o on o.id = r.label_org_id
  left join public.stations s on s.id = d.station_id
  where d.detected_at >= now() - make_interval(days => p_days)
    and (p_region is null or s.region = p_region)
  group by r.id, r.title, r.artist_name, o.name
  order by count(*) desc, r.title
  limit least(greatest(p_limit, 1), 500)
$$;

create or replace function public.detection_heatmap(p_days int default 7)
returns table (region text, dow int, block int, detections bigint)
language sql stable set search_path = public as $$
  select s.region,
         extract(isodow from d.detected_at at time zone 'Africa/Kampala')::int,
         (extract(hour from d.detected_at at time zone 'Africa/Kampala')::int / 4),
         count(*)
  from public.detections d join public.stations s on s.id = d.station_id
  where d.detected_at >= now() - make_interval(days => p_days) and s.region is not null
  group by 1, 2, 3
$$;

-- ── Public site (SECURITY DEFINER, aggregates only) ────────────────────────
create or replace function public.public_top_chart(p_region text default null, p_days int default 7)
returns table (rank bigint, title text, artist text, spins bigint)
language sql stable security definer set search_path = public as $$
  select row_number() over (order by count(*) desc, r.title), r.title, r.artist_name, count(*)
  from public.detections d
  join public.recordings r on r.id = d.recording_id
  left join public.stations s on s.id = d.station_id
  where d.detected_at >= now() - make_interval(days => least(greatest(p_days, 1), 31))
    and (p_region is null or s.region = p_region)
  group by r.id, r.title, r.artist_name
  order by count(*) desc, r.title
  limit 10
$$;

create or replace function public.public_platform_stats()
returns table (streams_online bigint, venues bigint, detections_24h bigint)
language sql stable security definer set search_path = public as $$
  select (select count(*) from public.stations where stream_status = 'online'),
         (select count(*) from public.venues),
         (select count(*) from public.detections where detected_at >= now() - interval '24 hours')
$$;

revoke execute on function public.public_top_chart(text, int) from public;
revoke execute on function public.public_platform_stats() from public;
grant execute on function public.public_top_chart(text, int) to anon, authenticated;
grant execute on function public.public_platform_stats() to anon, authenticated;

-- Artists see the whole split sheet of recordings they own (not just their own line).
drop policy if exists splits_read on public.split_shares;
create policy splits_read on public.split_shares for select using (
  public.my_role() = 'cmo'
  or party_profile_id = auth.uid()
  or exists (select 1 from public.recordings r where r.id = recording_id and (
       (public.my_role() = 'label' and r.label_org_id = public.my_org())
    or (public.my_role() = 'artist' and r.artist_profile_id = auth.uid())))
);

-- The ingest worker reports 'failed' for a stream it can't read at all.
alter table public.stations drop constraint if exists stations_stream_status_check;
alter table public.stations add constraint stations_stream_status_check
  check (stream_status in ('starting', 'online', 'reconnecting', 'no_stream_url', 'failed', 'disabled'));

-- ==========================================================================
-- 4. 0004_realtime.sql
-- Realtime: publish detections, stations and unmatched clips
-- ==========================================================================

-- Realtime: let dashboards hear about new airplay the moment it is detected,
-- instead of waiting for the next poll.
--
-- Realtime honours RLS, so a label still only receives rows it could select.
-- Every block is idempotent: Supabase projects already have a
-- `supabase_realtime` publication, while a bare PostgreSQL (the CI shim) does
-- not — that case is a no-op rather than an error.

do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    return;
  end if;

  foreach t in array array['detections', 'stations', 'unmatched_clips'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;

-- ==========================================================================
-- 5. 0005_alerts.sql
-- Alerts: outbox, per-person switches, first-spin/chart/dispute enqueue
-- ==========================================================================

-- ── Alert outbox: from a detected play to a WhatsApp/email message ─────────
--
-- The database decides *who* should hear about something and writes a row per
-- recipient. Delivery (WhatsApp Cloud API, email) happens outside Postgres in
-- `/api/cron/alerts`, which can retry safely because every row is idempotent
-- per recipient.

create table if not exists public.alert_outbox (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('firstspin', 'chart', 'dispute', 'payout')),
  title text not null,
  body text not null,
  link text,
  -- e.g. 'firstspin:<recording>:<station>' — one alert per person per event,
  -- no matter how many times the enqueue function runs.
  dedupe_key text not null,
  created_at timestamptz not null default now(),
  sent_at timestamptz,
  channel text check (channel in ('whatsapp', 'email')),
  attempts int not null default 0,
  last_error text,
  unique (profile_id, dedupe_key)
);
create index if not exists alert_outbox_pending_idx
  on public.alert_outbox (created_at) where sent_at is null;

alter table public.alert_outbox enable row level security;

-- People can read their own alert history; nobody writes from the browser.
drop policy if exists alert_outbox_self on public.alert_outbox;
create policy alert_outbox_self on public.alert_outbox for select using (profile_id = auth.uid());

-- Statements need to know when they appeared, so a new one can be announced.
alter table public.royalty_statements add column if not exists created_at timestamptz not null default now();

-- ── Per-person switches ───────────────────────────────────────────────────
-- An absent row (or an absent key) means the default: plays, charts and
-- disputes on; statements off. That matches the settings screen.
create or replace function public.alert_wanted(p_profile uuid, p_kind text)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select (events ->> p_kind)::boolean from public.alert_prefs where profile_id = p_profile),
    p_kind <> 'payout'
  )
$$;

-- ── Enqueue everything that happened since `p_since` ──────────────────────
create or replace function public.enqueue_alerts(p_since timestamptz default null, p_limit int default 200)
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_since timestamptz := coalesce(p_since, now() - interval '1 hour');
  v_total int := 0;
  v_n int;
begin
  -- First spin on a station: the first time this track is heard there.
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select distinct p.id, 'firstspin',
         'First spin on ' || f.station,
         f.title || ' was just detected on ' || f.station || '. That is a new station for this recording.',
         '/dashboard/artist',
         'firstspin:' || f.recording_id || ':' || f.station_id
  from (
    select d.recording_id, d.station_id, rec.title,
           coalesce(st.name, 'a monitored stream') as station
    from public.detections d
    join public.recordings rec on rec.id = d.recording_id
    left join public.stations st on st.id = d.station_id
    where d.recording_id is not null
      and d.station_id is not null
      and d.detected_at >= v_since
      and not exists (
        select 1 from public.detections e
        where e.recording_id = d.recording_id
          and e.station_id = d.station_id
          and (e.detected_at < d.detected_at or (e.detected_at = d.detected_at and e.id < d.id))
      )
    limit p_limit
  ) f
  join public.profiles p on p.approved and (p.id = (select artist_profile_id from public.recordings where id = f.recording_id)
    or p.org_id = (select label_org_id from public.recordings where id = f.recording_id))
  where public.alert_wanted(p.id, 'firstspin')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- A dispute names two claimants: both sides hear about it immediately.
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select distinct p.id, 'dispute',
         'Ownership dispute opened',
         coalesce(rec.title, 'A recording') || ' now has two claimants. An auditor will review the split before any royalty is paid.',
         '/dashboard/label',
         'dispute:' || d.id
  from public.disputes d
  left join public.recordings rec on rec.id = d.recording_id
  join public.profiles p on p.approved and (p.org_id = d.claimant_a or p.org_id = d.claimant_b)
  where d.opened_at >= v_since
    and public.alert_wanted(p.id, 'dispute')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- A new royalty statement is a money event; nobody wants to miss it.
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select distinct p.id, 'payout',
         'Royalty statement ready',
         'Your statement for ' || to_char(s.period, 'FMMonth YYYY') || ' is ready: '
           || to_char(s.amount_ugx, 'FM999,999,999') || ' UGX (' || s.status || ').',
         '/dashboard/label',
         'payout:' || s.id
  from public.royalty_statements s
  join public.profiles p on p.approved and (p.id = s.profile_id or p.org_id = s.org_id)
  where s.created_at >= v_since
    and public.alert_wanted(p.id, 'payout')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  return v_total;
end $$;

-- ── Weekly chart movement ─────────────────────────────────────────────────
-- Run once a week (not hourly): compares this week with last week and tells
-- rights holders about new entries and climbers.
create or replace function public.enqueue_chart_alerts(p_now timestamptz default null)
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_now timestamptz := coalesce(p_now, now());
  v_week text := to_char(coalesce(p_now, now()), 'IYYY-IW');
  v_total int;
begin
  with cur as (
    select d.recording_id, count(*)::int as spins
    from public.detections d
    where d.recording_id is not null and d.detected_at >= v_now - interval '7 days'
    group by 1
  ), prev as (
    select d.recording_id, count(*)::int as spins
    from public.detections d
    where d.recording_id is not null
      and d.detected_at >= v_now - interval '14 days'
      and d.detected_at < v_now - interval '7 days'
    group by 1
  ), ranked as (
    select c.recording_id, rank() over (order by c.spins desc) as pos, c.spins,
           coalesce(p.spins, 0) as prev_spins
    from cur c left join prev p on p.recording_id = c.recording_id
  )
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select distinct pr.id, 'chart',
         'Chart entry: ' || r.title,
         r.title || ' is #' || k.pos || ' this week with ' || k.spins || ' plays'
           || case when k.prev_spins = 0 then ' — a new entry.' else ' (up from ' || k.prev_spins || ').' end,
         '/dashboard/artist',
         'chart:' || k.recording_id || ':' || v_week
  from ranked k
  join public.recordings r on r.id = k.recording_id
  join public.profiles pr on pr.approved
    and (pr.id = r.artist_profile_id or pr.org_id = r.label_org_id)
  where k.pos <= 100
    and k.spins > k.prev_spins
    and public.alert_wanted(pr.id, 'chart')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_total = row_count;
  return v_total;
end $$;

-- Delivery is server-side only: the anon/authenticated roles cannot enqueue.
revoke execute on function public.enqueue_alerts(timestamptz, int) from public, anon, authenticated;
revoke execute on function public.enqueue_chart_alerts(timestamptz) from public, anon, authenticated;
grant execute on function public.enqueue_alerts(timestamptz, int) to service_role;
grant execute on function public.enqueue_chart_alerts(timestamptz) to service_role;

-- ==========================================================================
-- 6. 0006_public_ingest_health.sql
-- Public ingest health: station count and last detection for /setup
-- ==========================================================================

-- Public ingest health: counts and timestamps only, for /setup and /api/health.
--
-- Those pages run with the anon key, and row-level security (correctly) hides
-- every station and detection from an anonymous caller — so without this the
-- readiness board always reported "no stations" and "no detections" on a
-- perfectly healthy deployment. This function answers the two questions the
-- board needs and nothing more: no names, no stream URLs, no rows.

create or replace function public.public_ingest_health()
returns json
language sql
stable
security definer
set search_path = public
as $$
  select json_build_object(
    'stations',       (select count(*) from public.stations),
    'monitored',      (select count(*) from public.stations
                        where stream_status in ('starting', 'online', 'reconnecting')),
    'last_heartbeat', (select max(last_heartbeat) from public.stations),
    'last_detection', (select max(detected_at) from public.detections)
  );
$$;

revoke all on function public.public_ingest_health() from public;
grant execute on function public.public_ingest_health() to anon, authenticated;

-- ==========================================================================
-- 7. 0007_brand_mentions.sql
-- Brand mentions: tracked brands, spoken mentions, review
-- ==========================================================================

-- Brand mentions: brands spoken on air (live reads, presenter shout-outs),
-- found by the ingest worker's speech recognition. Pre-recorded adverts are
-- caught more reliably by fingerprinting (enroll the ad like a song).
--
-- Who sees what:
--   CMO          manages the tracked-brand list; sees and reviews every mention
--   Broadcaster  sees mentions on its own stations (read-only)
--   everyone else nothing
-- The worker writes with the service-role key.

create table if not exists public.tracked_keywords (
  id uuid primary key default gen_random_uuid(),
  brand text not null check (length(trim(brand)) between 1 and 80),
  -- how people say it, e.g. {mtn, "m t n", "em tee en"}
  terms text[] not null default '{}' check (cardinality(terms) between 1 and 20),
  -- how the recogniser has misheard it, confirmed by a reviewer, e.g. {"mt and"}
  aliases text[] not null default '{}' check (cardinality(aliases) <= 50),
  active boolean not null default true,
  created_by uuid references public.profiles (id) default auth.uid(),
  created_at timestamptz not null default now()
);
create unique index if not exists tracked_keywords_brand on public.tracked_keywords (lower(brand));

create table if not exists public.mentions (
  id bigint generated always as identity primary key,
  station_id uuid not null references public.stations (id) on delete cascade,
  keyword_id uuid references public.tracked_keywords (id) on delete set null,
  brand text not null,
  heard_at timestamptz not null,
  heard text not null,                       -- the words that matched
  transcript text not null check (length(transcript) <= 1000),
  score int check (score between 0 and 100),
  evidence_path text,
  status text not null default 'unreviewed' check (status in ('unreviewed', 'confirmed', 'rejected')),
  reviewed_by uuid references public.profiles (id),
  reviewed_at timestamptz
);
create index if not exists mentions_station_time on public.mentions (station_id, heard_at desc);
create index if not exists mentions_time on public.mentions (heard_at desc);

alter table public.tracked_keywords enable row level security;
alter table public.mentions enable row level security;

create policy tracked_keywords_cmo_read on public.tracked_keywords for select using (public.my_role() = 'cmo');
create policy tracked_keywords_cmo_insert on public.tracked_keywords for insert with check (public.my_role() = 'cmo');
create policy tracked_keywords_cmo_update on public.tracked_keywords for update
  using (public.my_role() = 'cmo') with check (public.my_role() = 'cmo');

create policy mentions_read on public.mentions for select using (
  public.my_role() = 'cmo'
  or exists (select 1 from public.stations s where s.id = station_id
             and public.my_role() = 'broadcaster' and s.broadcaster_org_id = public.my_org())
);
create policy mentions_cmo_review on public.mentions for update
  using (public.my_role() = 'cmo') with check (public.my_role() = 'cmo');

-- A review may change the verdict only — never the evidence itself.
create or replace function public.mentions_review_only() returns trigger
language plpgsql as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' and current_user not in ('postgres', 'supabase_admin') and (
       new.station_id <> old.station_id or new.brand <> old.brand or new.heard_at <> old.heard_at
       or new.heard <> old.heard or new.transcript <> old.transcript
       or new.evidence_path is distinct from old.evidence_path or new.keyword_id is distinct from old.keyword_id) then
    raise exception 'only the review status of a mention can be changed';
  end if;
  return new;
end $$;
drop trigger if exists mentions_review_only on public.mentions;
create trigger mentions_review_only before update on public.mentions
  for each row execute function public.mentions_review_only();

-- Evidence clips: readable exactly when the detection, unmatched clip or mention is.
drop policy if exists evidence_read on storage.objects;
create policy evidence_read on storage.objects for select using (
  bucket_id = 'evidence' and (
    exists (select 1 from public.detections d where d.evidence_path = name)
    or exists (select 1 from public.unmatched_clips u where u.evidence_path = name)
    or exists (select 1 from public.mentions m where m.evidence_path = name)
  ));

-- Starter list (the CMO edits it in the dashboard). Names only; no claims about sponsorship.
insert into public.tracked_keywords (brand, terms, aliases, created_by) values
  ('MTN', '{mtn,"m t n","em tee en"}', '{"mt and","empty n"}', null),
  ('Airtel', '{airtel,"air tel"}', '{}', null),
  ('Stanbic Bank', '{stanbic,"stanbic bank"}', '{}', null),
  ('Nile Special', '{"nile special"}', '{}', null),
  ('Club Pilsener', '{"club pilsener","club pilsner"}', '{}', null),
  ('Bell Lager', '{"bell lager"}', '{}', null),
  ('Uganda Waragi', '{"uganda waragi",waragi}', '{}', null),
  ('Coca-Cola', '{"coca cola",coke}', '{}', null),
  ('Mukwano', '{mukwano}', '{}', null),
  ('Rwenzori Water', '{rwenzori}', '{}', null)
on conflict do nothing;

-- ==========================================================================
-- 8. 0008_masters_upload.sql
-- Masters: upload songs with details; artists upload their own; security fixes
-- ==========================================================================

-- Masters: upload a song with its details, then the worker learns to recognise it.
--
-- Until now the dashboard only analysed a file in the browser and had nowhere
-- to put it — no way to create a recording, nothing stored — so an upload was
-- lost on sign-out and the worker never heard the song.
--
-- Now: the browser creates the recording (title, artist, codes, credits),
-- uploads a small *reference copy* (mono, 11 kHz — exactly what the
-- fingerprinter uses, a few MB per song, never the full-quality master) to the
-- private `masters` bucket, and the worker enrols every recording that has a
-- reference but is not yet enrolled.
--
-- Who may do what:
--   Label    create / edit / delete recordings of its own organisation
--   Artist   create / edit / delete their own self-released recordings
--            (label releases stay with the label)
--   CMO      read everything (unchanged)
--   Worker   service-role key: reads references, marks them enrolled

alter table public.recordings
  add column if not exists featuring text,
  add column if not exists producer text,
  add column if not exists genre text,
  add column if not exists master_path text,
  add column if not exists enrolled_at timestamptz,
  add column if not exists enroll_error text;

-- Independent artists upload their own songs.
drop policy if exists recordings_write_artist on public.recordings;
create policy recordings_write_artist on public.recordings for insert
  with check (public.my_role() = 'artist' and artist_profile_id = auth.uid() and label_org_id is null);
drop policy if exists recordings_update_artist on public.recordings;
create policy recordings_update_artist on public.recordings for update
  using (public.my_role() = 'artist' and artist_profile_id = auth.uid() and label_org_id is null)
  with check (artist_profile_id = auth.uid() and label_org_id is null);

-- Mistakes can be removed (a recording with airplay history is kept: the
-- detections reference it, so the delete is refused).
drop policy if exists recordings_delete_label on public.recordings;
create policy recordings_delete_label on public.recordings for delete
  using (public.my_role() = 'label' and label_org_id = public.my_org());
drop policy if exists recordings_delete_artist on public.recordings;
create policy recordings_delete_artist on public.recordings for delete
  using (public.my_role() = 'artist' and artist_profile_id = auth.uid() and label_org_id is null);

-- Private bucket for reference copies. 25 MB is ~20 minutes of reference audio.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('masters', 'masters', false, 26214400, array['audio/wav', 'audio/x-wav', 'audio/wave'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- Objects live at <recording id>/<file>; whoever owns the recording owns the file.
create or replace function public.owns_master(p_name text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.recordings r
    where r.id::text = split_part(p_name, '/', 1) and (
         (public.my_role() = 'label' and r.label_org_id = public.my_org())
      or (public.my_role() = 'artist' and r.artist_profile_id = auth.uid() and r.label_org_id is null)
    ));
$$;
revoke all on function public.owns_master(text) from public;
grant execute on function public.owns_master(text) to authenticated;

drop policy if exists masters_owner_read on storage.objects;
create policy masters_owner_read on storage.objects for select to authenticated
  using (bucket_id = 'masters' and (public.owns_master(name) or public.my_role() = 'cmo'));
drop policy if exists masters_owner_insert on storage.objects;
create policy masters_owner_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'masters' and public.owns_master(name));
drop policy if exists masters_owner_update on storage.objects;
create policy masters_owner_update on storage.objects for update to authenticated
  using (bucket_id = 'masters' and public.owns_master(name))
  with check (bucket_id = 'masters' and public.owns_master(name));
drop policy if exists masters_owner_delete on storage.objects;
create policy masters_owner_delete on storage.objects for delete to authenticated
  using (bucket_id = 'masters' and public.owns_master(name));

-- Hardening flagged by the Supabase security advisor -------------------------
-- 1. Functions with a fixed search path, so a caller can't shadow `public`.
alter function public.mentions_review_only() set search_path = public;
alter function public.lock_profile_fields() set search_path = public;
-- 2. alert_wanted() reveals one person's alert switches; only the (definer)
--    alert functions need it, never an API caller.
revoke execute on function public.alert_wanted(uuid, text) from public, anon, authenticated;

-- ==========================================================================
-- 9. 0009_public_stats_honest.sql
-- Homepage counts only stations that reported recently; permission tidy
-- ==========================================================================

-- Public numbers on the homepage must reflect reality.
--
-- public_platform_stats() counted any station whose last status was 'online',
-- so if the ingest worker stopped, the homepage would still claim those
-- stations were live. Count only stations that reported in the last 10 minutes.
create or replace function public.public_platform_stats()
returns table (streams_online bigint, venues bigint, detections_24h bigint)
language sql stable security definer set search_path = public as $$
  select (select count(*) from public.stations
           where stream_status = 'online' and last_heartbeat > now() - interval '10 minutes'),
         (select count(*) from public.venues),
         (select count(*) from public.detections where detected_at >= now() - interval '24 hours')
$$;
revoke execute on function public.public_platform_stats() from public;
grant execute on function public.public_platform_stats() to anon, authenticated;

-- owns_master() is only used by storage policies for signed-in users; Supabase
-- grants new functions to anon by default, so take that back explicitly.
revoke execute on function public.owns_master(text) from anon;

-- ==========================================================================
-- 10. 0010_airplay_alerts.sql
-- Airplay alerts: every play, daily summary, settings fix
-- ==========================================================================

-- ── Airplay alerts: every play, daily summary, settings that actually apply ──
--
-- 1. Two new alert kinds:
--      play   one message per detected play (off by default: a hit song can
--             be played dozens of times a day)
--      daily  one summary per person per day: yesterday's plays, by song and
--             station (on by default)
-- 2. Fix: the settings screen saves `firstSpin`, but alert_wanted() looked up
--    `firstspin`, so switching first-spin alerts off had no effect.
-- 3. Links point at the dashboard of the person's own role.
--
-- Delivery stays outside Postgres (the monitoring worker, or /api/cron/alerts).

alter table public.alert_outbox drop constraint if exists alert_outbox_kind_check;
alter table public.alert_outbox add constraint alert_outbox_kind_check
  check (kind in ('firstspin', 'play', 'daily', 'chart', 'dispute', 'payout'));

-- Settings keys as the dashboard saves them → the kind used here.
create or replace function public.alert_wanted(p_profile uuid, p_kind text)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select coalesce(events ->> p_kind,
                     events ->> case p_kind when 'firstspin' then 'firstSpin' when 'play' then 'everyPlay'
                                            when 'daily' then 'dailySummary' else p_kind end)::boolean
     from public.alert_prefs where profile_id = p_profile),
    p_kind not in ('payout', 'play')
  )
$$;
revoke execute on function public.alert_wanted(uuid, text) from public, anon, authenticated;

create or replace function public.alert_link(p_role public.app_role)
returns text language sql immutable set search_path = public as $$
  select case p_role when 'label' then '/dashboard/label' when 'cmo' then '/dashboard/cmo'
                     when 'broadcaster' then '/dashboard/broadcaster' when 'venue' then '/dashboard/venue'
                     else '/dashboard/artist' end
$$;

create or replace function public.kampala_time(p_at timestamptz)
returns text language sql immutable set search_path = public as $$
  select to_char(p_at at time zone 'Africa/Kampala', 'HH24:MI')
$$;

-- ── Enqueue everything that happened since `p_since` ──────────────────────
create or replace function public.enqueue_alerts(p_since timestamptz default null, p_limit int default 200)
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_since timestamptz := coalesce(p_since, now() - interval '1 hour');
  v_total int := 0;
  v_n int;
begin
  -- Recent plays of catalogue songs, each with "is this the first time on this station?".
  create temporary table if not exists _recent_plays (
    detection_id bigint, recording_id uuid, station_id uuid, detected_at timestamptz,
    duration_sec int, title text, station text, first_on_station boolean
  ) on commit drop;
  truncate _recent_plays;
  insert into _recent_plays
  select d.id, d.recording_id, d.station_id, d.detected_at, d.duration_sec, rec.title,
         coalesce(st.name, 'a monitored station') || coalesce(' ' || nullif(st.frequency, ''), ''),
         not exists (
           select 1 from public.detections e
           where e.recording_id = d.recording_id and e.station_id = d.station_id
             and (e.detected_at < d.detected_at or (e.detected_at = d.detected_at and e.id < d.id)))
  from public.detections d
  join public.recordings rec on rec.id = d.recording_id
  left join public.stations st on st.id = d.station_id
  where d.recording_id is not null and d.station_id is not null and d.detected_at >= v_since
  order by d.detected_at
  limit p_limit;

  -- Every play (for people who asked for it). Says so when it is a first spin,
  -- and replaces the separate first-spin message for them.
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select distinct p.id, 'play',
         'Played on ' || f.station || ': ' || f.title,
         f.title || ' was played on ' || f.station || ' at ' || public.kampala_time(f.detected_at) || ' (Kampala time)'
           || case when f.duration_sec >= 60 then ', ' || (f.duration_sec / 60) || ' min ' || (f.duration_sec % 60) || ' s.'
                   else ', ' || f.duration_sec || ' s.' end
           || case when f.first_on_station then ' This is its first play on this station.' else '' end,
         public.alert_link(p.role),
         'play:' || f.detection_id
  from _recent_plays f
  join public.recordings r on r.id = f.recording_id
  join public.profiles p on p.approved and (p.id = r.artist_profile_id or p.org_id = r.label_org_id)
  where public.alert_wanted(p.id, 'play')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- First spin on a station: the first time this song is heard there.
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select distinct p.id, 'firstspin',
         'First play on ' || f.station || ': ' || f.title,
         f.title || ' was just played on ' || f.station || ' for the first time, at '
           || public.kampala_time(f.detected_at) || ' (Kampala time).',
         public.alert_link(p.role),
         'firstspin:' || f.recording_id || ':' || f.station_id
  from _recent_plays f
  join public.recordings r on r.id = f.recording_id
  join public.profiles p on p.approved and (p.id = r.artist_profile_id or p.org_id = r.label_org_id)
  where f.first_on_station
    and public.alert_wanted(p.id, 'firstspin')
    and not public.alert_wanted(p.id, 'play')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- A dispute names two claimants: both sides hear about it immediately.
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select distinct p.id, 'dispute',
         'Ownership dispute opened',
         coalesce(rec.title, 'A recording') || ' now has two claimants. An auditor will review the split before any royalty is paid.',
         public.alert_link(p.role),
         'dispute:' || d.id
  from public.disputes d
  left join public.recordings rec on rec.id = d.recording_id
  join public.profiles p on p.approved and (p.org_id = d.claimant_a or p.org_id = d.claimant_b)
  where d.opened_at >= v_since
    and public.alert_wanted(p.id, 'dispute')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- A new royalty statement is a money event; nobody wants to miss it.
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select distinct p.id, 'payout',
         'Royalty statement ready',
         'Your statement for ' || to_char(s.period, 'FMMonth YYYY') || ' is ready: '
           || to_char(s.amount_ugx, 'FM999,999,999') || ' UGX (' || s.status || ').',
         public.alert_link(p.role),
         'payout:' || s.id
  from public.royalty_statements s
  join public.profiles p on p.approved and (p.id = s.profile_id or p.org_id = s.org_id)
  where s.created_at >= v_since
    and public.alert_wanted(p.id, 'payout')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  return v_total;
end $$;

-- ── Daily summary: yesterday in Kampala, per person ───────────────────────
-- Safe to call any number of times: one row per person per day.
create or replace function public.enqueue_daily_alerts(p_day date default null)
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_day date := coalesce(p_day, (now() at time zone 'Africa/Kampala')::date - 1);
  v_from timestamptz := (v_day::timestamp at time zone 'Africa/Kampala');
  v_to timestamptz := ((v_day + 1)::timestamp at time zone 'Africa/Kampala');
  v_total int;
begin
  with plays as (
    select p.id as profile_id, p.role, d.recording_id, rec.title,
           coalesce(st.name, v.name, 'a venue') as station, d.venue_id is not null as at_venue
    from public.detections d
    join public.recordings rec on rec.id = d.recording_id
    left join public.stations st on st.id = d.station_id
    left join public.venues v on v.id = d.venue_id
    join public.profiles p on p.approved and (p.id = rec.artist_profile_id or p.org_id = rec.label_org_id)
    where d.detected_at >= v_from and d.detected_at < v_to
  ), by_station as (
    select profile_id, recording_id, title, station, count(*) as n
    from plays group by 1, 2, 3, 4
  ), by_song as (
    select profile_id, recording_id, title, sum(n) as n,
           string_agg(station || ' ' || n, ', ' order by n desc, station) as stations
    from by_station group by 1, 2, 3
  ), per_person as (
    select s.profile_id, sum(s.n)::int as plays,
           (select count(distinct station) from plays x where x.profile_id = s.profile_id and not x.at_venue) as stations,
           (select count(distinct station) from plays x where x.profile_id = s.profile_id and x.at_venue) as venues,
           string_agg('• ' || s.title || ' — ' || s.n || case when s.n = 1 then ' play (' else ' plays (' end || s.stations || ')',
                      E'\n' order by s.n desc, s.title) as lines
    from by_song s group by 1
  )
  insert into public.alert_outbox (profile_id, kind, title, body, link, dedupe_key)
  select pp.profile_id, 'daily',
         'Your airplay for ' || to_char(v_day, 'FMDy FMDD FMMon') || ': ' || pp.plays || case when pp.plays = 1 then ' play' else ' plays' end,
         'Yesterday your music was played ' || pp.plays || case when pp.plays = 1 then ' time' else ' times' end
           || ' on ' || concat_ws(' and ',
                nullif(pp.stations || case when pp.stations = 1 then ' station' else ' stations' end, '0 stations'),
                nullif(pp.venues || case when pp.venues = 1 then ' venue' else ' venues' end, '0 venues')) || '.'
           || E'\n\n' || left(pp.lines, 700),
         public.alert_link(pr.role),
         'daily:' || v_day
  from per_person pp
  join public.profiles pr on pr.id = pp.profile_id
  where public.alert_wanted(pp.profile_id, 'daily')
  on conflict (profile_id, dedupe_key) do nothing;
  get diagnostics v_total = row_count;
  return v_total;
end $$;

-- Delivery is server-side only.
revoke execute on function public.enqueue_alerts(timestamptz, int) from public, anon, authenticated;
revoke execute on function public.enqueue_daily_alerts(date) from public, anon, authenticated;
grant execute on function public.enqueue_alerts(timestamptz, int) to service_role;
grant execute on function public.enqueue_daily_alerts(date) to service_role;

-- ==========================================================================
-- 11. 0011_upc_check.sql
-- Upload form: warn when a UPC is already used by another artist
-- ==========================================================================

-- ── UPC sanity check for the upload form ──────────────────────────────────
-- A UPC identifies one release (single/EP/album), so every track on it has the
-- same main artist — unless it's a compilation. RLS hides other accounts'
-- songs, so the form can't see a clash itself. This answers one yes/no
-- question and reveals nothing else (no titles, owners or ids).
create or replace function public.upc_used_by_other_artist(p_upc text, p_artist text, p_exclude uuid default null)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.recordings r
    where r.upc = nullif(trim(p_upc), '')
      and (p_exclude is null or r.id <> p_exclude)
      and lower(trim(coalesce(r.artist_name, ''))) <> lower(trim(coalesce(p_artist, '')))
  )
$$;
revoke execute on function public.upc_used_by_other_artist(text, text, uuid) from public, anon;
grant execute on function public.upc_used_by_other_artist(text, text, uuid) to authenticated;

-- ==========================================================================
-- 12. 0012_alert_channels.sql
-- Airplay alerts on WhatsApp and SMS as well as email
-- ==========================================================================

-- ── Airplay alerts on WhatsApp and SMS, not just email ─────────────────────
-- Each person picks their channels; the mobile number already saved for
-- WhatsApp (alert_prefs.whatsapp_e164) is used for SMS too. Email stays on by
-- default; WhatsApp and SMS are opt-in.
alter table public.alert_prefs
  add column if not exists channels jsonb not null default '{"email": true, "whatsapp": false, "sms": false}'::jsonb;

-- One outbox row per alert, delivered on several channels. `delivered` keeps
-- each channel's result ("sent" or the last error), so a retry after one
-- channel fails never sends the others twice. `channel` lists what went out,
-- e.g. 'email+sms'.
alter table public.alert_outbox add column if not exists delivered jsonb not null default '{}'::jsonb;
alter table public.alert_outbox drop constraint if exists alert_outbox_channel_check;
alter table public.alert_outbox add constraint alert_outbox_channel_check
  check (channel is null or channel ~ '^(email|whatsapp|sms)(\+(email|whatsapp|sms))*$');

-- ==========================================================================
-- 13. 0013_public_stats.sql
-- Aggregate counts for the public website
-- ==========================================================================

-- Public, aggregate-only numbers for the website (no rows, no names, no audio).
-- Security definer so anonymous visitors can read the counts without seeing any table.
create or replace function public.public_stats()
returns json
language sql
stable
security definer
set search_path = public
as $$
  select json_build_object(
    'stations_live',  (select count(*) from stations where stream_status = 'online' and last_heartbeat > now() - interval '15 minutes'),
    'stations_total', (select count(*) from stations where stream_status is distinct from 'disabled'),
    'songs',          (select count(*) from recordings where enrolled_at is not null),
    'plays_7d',       (select count(*) from detections where detected_at > now() - interval '7 days'),
    'clips_24h',      (select count(*) from unmatched_clips where heard_at > now() - interval '24 hours'),
    'as_of',          now()
  );
$$;

revoke all on function public.public_stats() from public;
grant execute on function public.public_stats() to anon, authenticated;

-- ==========================================================================
-- 14. 0014_public_coverage.sql
-- Coverage: anonymous per-region station counts for /coverage
-- ==========================================================================

-- ── Public coverage: how much of Uganda we actually listen to ─────────────
--
-- The marketing claim that matters against global services ("26 stations
-- across four regions, not two or three in Kampala") has to be answerable
-- without a login, and without exposing station names or stream URLs.
--
-- Counts only: how many stations per region, how many are monitored right now,
-- and when the worker last checked in.

create or replace function public.public_coverage()
returns json
language sql
stable
security definer
set search_path = public
as $$
  with per_region as (
    select
      coalesce(region, 'Unspecified') as region,
      count(*) as stations,
      count(*) filter (where stream_status in ('starting', 'online', 'reconnecting')) as monitored,
      count(*) filter (where stream_status = 'online') as live
    from public.stations
    group by 1
  )
  select json_build_object(
    'stations',   (select count(*) from public.stations),
    'monitored',  (select count(*) from public.stations
                    where stream_status in ('starting', 'online', 'reconnecting')),
    'live',       (select count(*) from public.stations where stream_status = 'online'),
    'regions',    (select coalesce(json_agg(json_build_object(
                     'region', region, 'stations', stations,
                     'monitored', monitored, 'live', live
                   ) order by region), '[]'::json) from per_region),
    'last_heartbeat', (select max(last_heartbeat) from public.stations),
    'last_detection', (select max(detected_at) from public.detections)
  );
$$;

revoke all on function public.public_coverage() from public;
grant execute on function public.public_coverage() to anon, authenticated;

-- ==========================================================================
-- 15. 0015_cmo_station_report.sql
-- CMO pack: per-station monthly report and monthly top works
-- ==========================================================================

-- ── CMO distribution pack: per-station monthly report + monthly top works ──
--
-- UPRS (and any CMO) distributes money per station, per month. The numbers they
-- need are: how many plays each station generated, how many distinct works and
-- artists that represents, and how many of those plays carry an evidence clip.
--
-- Both functions are SECURITY INVOKER on purpose: whoever calls them sees only
-- the detections their RLS already allows. A CMO sees the whole panel; a label
-- sees its own catalogue; nobody sees more through the report than through the
-- dashboard. The feed endpoint uses the same rule.

create or replace function public.station_month_report(p_from date, p_to date)
returns table (
  station_id uuid,
  station text,
  region text,
  spins bigint,
  works bigint,
  artists bigint,
  with_evidence bigint,
  first_play timestamptz,
  last_play timestamptz
)
language sql
stable
set search_path = public
as $$
  select
    s.id,
    s.name,
    s.region,
    count(d.id) as spins,
    count(distinct d.recording_id) as works,
    count(distinct r.artist_name) as artists,
    count(*) filter (where d.evidence_path is not null) as with_evidence,
    min(d.detected_at),
    max(d.detected_at)
  from public.detections d
  join public.stations s on s.id = d.station_id
  left join public.recordings r on r.id = d.recording_id
  where d.detected_at >= (p_from::timestamp at time zone 'Africa/Kampala')
    and d.detected_at <  ((p_to + 1)::timestamp at time zone 'Africa/Kampala')
  group by s.id, s.name, s.region
  order by count(d.id) desc, s.name
$$;

create or replace function public.month_top_works(p_from date, p_to date, p_limit int default 20)
returns table (rank bigint, title text, artist text, owner text, spins bigint, stations bigint)
language sql
stable
set search_path = public
as $$
  select row_number() over (order by count(*) desc, r.title),
         r.title,
         r.artist_name,
         o.name,
         count(*),
         count(distinct d.station_id)
  from public.detections d
  join public.recordings r on r.id = d.recording_id
  left join public.organizations o on o.id = r.label_org_id
  where d.detected_at >= (p_from::timestamp at time zone 'Africa/Kampala')
    and d.detected_at <  ((p_to + 1)::timestamp at time zone 'Africa/Kampala')
  group by r.id, r.title, r.artist_name, o.name
  order by count(*) desc, r.title
  limit least(greatest(p_limit, 1), 100)
$$;

revoke all on function public.station_month_report(date, date) from public;
revoke all on function public.month_top_works(date, date, int) from public;
grant execute on function public.station_month_report(date, date) to authenticated;
grant execute on function public.month_top_works(date, date, int) to authenticated;

-- ==========================================================================
-- 16. 0016_tv_stations.sql
-- TV: stations are radio or television; coverage counts both
-- ==========================================================================

-- ── TV ingest: a station is now radio *or* television ─────────────────────
--
-- The monitor already pulls any stream ffmpeg can decode, so a TV channel is a
-- station row with `kind = 'tv'` and an HLS/RTMP URL. Keeping one table means
-- charts, evidence, alerts and the CMO pack work for TV without a second
-- pipeline — and the homepage can stop promising "TV next" once a channel is
-- actually in the panel.

alter table public.stations
  add column if not exists kind text not null default 'radio';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'stations_kind_check') then
    alter table public.stations
      add constraint stations_kind_check check (kind in ('radio', 'tv'));
  end if;
end $$;

create index if not exists stations_kind on public.stations (kind);

-- TV plays are recorded with their own source so reports can separate them
-- from radio without guessing from the station name.
alter table public.detections drop constraint if exists detections_source_check;
alter table public.detections
  add constraint detections_source_check
  check (source in ('stream', 'fm', 'venue', 'manual', 'tv'));

-- Coverage now reports radio and TV separately: "28 stations, 25 reporting"
-- is less useful than "25 radio, 3 TV".
create or replace function public.public_coverage()
returns json
language sql
stable
security definer
set search_path = public
as $$
  with per_region as (
    select
      coalesce(region, 'Unspecified') as region,
      count(*) as stations,
      count(*) filter (where kind = 'tv') as tv,
      count(*) filter (where stream_status in ('starting', 'online', 'reconnecting')) as monitored,
      count(*) filter (where stream_status = 'online') as live
    from public.stations
    group by 1
  )
  select json_build_object(
    'stations',   (select count(*) from public.stations),
    'radio',      (select count(*) from public.stations where kind = 'radio'),
    'tv',         (select count(*) from public.stations where kind = 'tv'),
    'monitored',  (select count(*) from public.stations
                    where stream_status in ('starting', 'online', 'reconnecting')),
    'live',       (select count(*) from public.stations where stream_status = 'online'),
    'regions',    (select coalesce(json_agg(json_build_object(
                     'region', region, 'stations', stations, 'tv', tv,
                     'monitored', monitored, 'live', live
                   ) order by region), '[]'::json) from per_region),
    'last_heartbeat', (select max(last_heartbeat) from public.stations),
    'last_detection', (select max(detected_at) from public.detections)
  );
$$;

revoke all on function public.public_coverage() from public;
grant execute on function public.public_coverage() to anon, authenticated;

-- ==========================================================================
-- 17. 0017_reach.sql
-- Reach: declared AQH per station, report carries kind and listen seconds
-- ==========================================================================

-- ── Reach & impressions: audience data is declared, never invented ─────────
--
-- Advertisers ask "how many people heard this?" and the honest answer needs a
-- per-station audience figure we did not make up. So the figure lives on the
-- station with its provenance attached: who supplied it and when it was
-- measured. No source, no number — the UI then shows "no audience data"
-- instead of a plausible fiction.
--
-- Methodology: docs/reach-methodology.md.
--   impressions ≈ Σ (plays × station AQH × clip duration / 15 min)
-- AQH = average quarter-hour listeners, the metric radio stations already sell
-- advertising against, so a station can supply it from its own survey or
-- agency rate card.

alter table public.stations
  add column if not exists aqh int check (aqh is null or aqh >= 0),
  add column if not exists audience_source text,
  add column if not exists audience_as_of date;

comment on column public.stations.aqh is
  'Average quarter-hour listeners, declared by the station or its agency. NULL = unknown, never estimated.';
comment on column public.stations.audience_source is
  'Who supplied the audience figure (survey name, agency, broadcaster document).';
comment on column public.stations.audience_as_of is
  'Date the audience figure was measured. Impressions are labelled as estimates of that date.';

-- The monthly report now carries kind and the audience figure, so the CMO pack
-- and the reach section use one query.
drop function if exists public.station_month_report(date, date);

create function public.station_month_report(p_from date, p_to date)
returns table (
  station_id uuid,
  station text,
  region text,
  kind text,
  spins bigint,
  works bigint,
  artists bigint,
  with_evidence bigint,
  first_play timestamptz,
  last_play timestamptz,
  aqh int,
  listen_seconds bigint
)
language sql
stable
set search_path = public
as $$
  select
    s.id,
    s.name,
    s.region,
    s.kind,
    count(d.id) as spins,
    count(distinct d.recording_id) as works,
    count(distinct r.artist_name) as artists,
    count(*) filter (where d.evidence_path is not null) as with_evidence,
    min(d.detected_at),
    max(d.detected_at),
    max(s.aqh) as aqh,
    coalesce(sum(d.duration_sec), 0) as listen_seconds
  from public.detections d
  join public.stations s on s.id = d.station_id
  left join public.recordings r on r.id = d.recording_id
  where d.detected_at >= (p_from::timestamp at time zone 'Africa/Kampala')
    and d.detected_at <  ((p_to + 1)::timestamp at time zone 'Africa/Kampala')
  group by s.id, s.name, s.region, s.kind
  order by count(d.id) desc, s.name
$$;

revoke all on function public.station_month_report(date, date) from public;
grant execute on function public.station_month_report(date, date) to authenticated;

-- ==========================================================================
-- 18. 0018_push_subscriptions.sql
-- Push: one row per installed device, owned by its profile
-- ==========================================================================

-- ── Web push: one row per browser a person has installed ───────────────────
--
-- Alerts already leave by email, WhatsApp and SMS from the worker. Push is the
-- "it's in my pocket" channel SongBoost sells, and it belongs to the same
-- person: a subscription is tied to the signed-in profile, so an artist can
-- only ever register their own devices.

create table if not exists public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  endpoint text not null unique,
  p256dh text not null,
  auth text not null,
  user_agent text,
  created_at timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  failures int not null default 0
);

create index if not exists push_subscriptions_profile on public.push_subscriptions (profile_id);

alter table public.push_subscriptions enable row level security;

drop policy if exists push_own_read on public.push_subscriptions;
create policy push_own_read on public.push_subscriptions for select
  using (profile_id = auth.uid() or public.my_role() = 'cmo');

drop policy if exists push_own_insert on public.push_subscriptions;
create policy push_own_insert on public.push_subscriptions for insert
  with check (profile_id = auth.uid());

drop policy if exists push_own_update on public.push_subscriptions;
create policy push_own_update on public.push_subscriptions for update
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());

drop policy if exists push_own_delete on public.push_subscriptions;
create policy push_own_delete on public.push_subscriptions for delete
  using (profile_id = auth.uid());

-- Called by /api/push/send when a push provider rejects a device (not 404/410).
create or replace function public.bump_push_failures(p_ids uuid[])
returns void
language sql
security definer
set search_path = public
as $$
  update public.push_subscriptions
     set failures = failures + 1
   where id = any(p_ids);
$$;

revoke all on function public.bump_push_failures(uuid[]) from public;
revoke all on function public.bump_push_failures(uuid[]) from anon, authenticated;

-- ==========================================================================
-- 19. 0019_plan_requests.sql
-- Plans: self-serve requests with a reference a human can bill
-- ==========================================================================

-- ── Self-serve plans: the request a person makes, not a payment we pretend ─
--
-- SongBoost's advantage is a $10 button. Ours is the same price point in
-- shillings, but money only moves once a mobile-money collection account is
-- live. Until then the honest product is a request that reaches a human with
-- everything needed to bill: plan, amount, number, reference.
--
-- When the MoMo API credentials exist, `status` moves pending → active from the
-- payment callback and nothing else in the app has to change.

create table if not exists public.plan_requests (
  id uuid primary key default gen_random_uuid(),
  reference text not null unique,
  profile_id uuid references public.profiles (id) on delete set null,
  org_id uuid references public.organizations (id) on delete set null,
  plan text not null check (plan in ('artist', 'label', 'broadcaster', 'venue', 'cmo')),
  billing text not null default 'monthly' check (billing in ('monthly', 'annual')),
  amount_ugx int not null check (amount_ugx >= 0),
  msisdn text,
  note text,
  status text not null default 'pending' check (status in ('pending', 'contacted', 'active', 'cancelled')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists plan_requests_status on public.plan_requests (status, created_at desc);
create index if not exists plan_requests_profile on public.plan_requests (profile_id);

alter table public.plan_requests enable row level security;

drop policy if exists plan_requests_own_read on public.plan_requests;
create policy plan_requests_own_read on public.plan_requests for select
  using (profile_id = auth.uid() or public.my_role() = 'cmo');

drop policy if exists plan_requests_own_insert on public.plan_requests;
create policy plan_requests_own_insert on public.plan_requests for insert
  with check (profile_id = auth.uid() and status = 'pending');

drop policy if exists plan_requests_own_cancel on public.plan_requests;
create policy plan_requests_own_cancel on public.plan_requests for update
  using (profile_id = auth.uid()) with check (profile_id = auth.uid() and status = 'cancelled');

drop policy if exists plan_requests_cmo_update on public.plan_requests;
create policy plan_requests_cmo_update on public.plan_requests for update
  using (public.my_role() = 'cmo');

-- ==========================================================================
-- 20. 0020_station_requests.sql
-- Station onboarding: broadcasters claim or add a station, CMO approves
-- ==========================================================================

-- ── Self-serve station onboarding ─────────────────────────────────────────
--
-- A broadcaster signing up had no way to say "this is my station" — the
-- dashboard just told them to ask East Sound. That is a dead end at the exact
-- moment someone is willing to work.
--
-- So a broadcaster can now submit a request: claim a station already in the
-- panel, or add a new one (with its stream URL). Approval stays with the CMO,
-- because linking an organisation to a station is a rights decision, not a
-- self-service toggle — and because a wrong link would expose someone else's
-- playout data.

create table if not exists public.station_requests (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  org_id uuid references public.organizations (id) on delete set null,
  station_id uuid references public.stations (id) on delete set null,
  name text,
  frequency text,
  region text,
  kind text not null default 'radio' check (kind in ('radio', 'tv')),
  stream_url text,
  note text,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'cancelled')),
  review_note text,
  created_at timestamptz not null default now(),
  reviewed_at timestamptz,
  reviewed_by uuid references public.profiles (id),
  constraint station_request_target check (
    station_id is not null or (name is not null and length(btrim(name)) > 1)
  )
);

create index if not exists station_requests_status on public.station_requests (status, created_at desc);
create index if not exists station_requests_profile on public.station_requests (profile_id);

alter table public.station_requests enable row level security;

drop policy if exists station_requests_own_insert on public.station_requests;
create policy station_requests_own_insert on public.station_requests for insert
  with check (profile_id = auth.uid() and status = 'pending');

drop policy if exists station_requests_read on public.station_requests;
create policy station_requests_read on public.station_requests for select
  using (profile_id = auth.uid() or public.my_role() = 'cmo');

drop policy if exists station_requests_own_cancel on public.station_requests;
create policy station_requests_own_cancel on public.station_requests for update
  using (profile_id = auth.uid())
  with check (profile_id = auth.uid() and status = 'cancelled');

-- Stations nobody has claimed yet. Name, region and frequency are public
-- information; a broadcaster cannot read the stations table directly, so this
-- SECURITY DEFINER function exposes exactly the fields needed to recognise
-- their own station — no stream URLs, no playout data.
create or replace function public.claimable_stations()
returns table (id uuid, name text, region text, frequency text, kind text)
language sql
stable
security definer
set search_path = public
as $$
  select s.id, s.name, s.region, s.frequency, s.kind
  from public.stations s
  where s.broadcaster_org_id is null
    and coalesce(s.stream_status, '') <> 'disabled'
  order by s.name
  limit 500
$$;

revoke all on function public.claimable_stations() from public;
grant execute on function public.claimable_stations() to authenticated;

-- Approving links the station to the requesting organisation (or creates it),
-- then marks the request approved. Only a CMO can do this.
create or replace function public.approve_station_request(p_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.station_requests;
  new_id uuid;
  new_slug text;
begin
  if public.my_role() is distinct from 'cmo' then
    raise exception 'only a CMO can approve a station request';
  end if;

  select * into r from public.station_requests where id = p_id for update;
  if not found then
    raise exception 'station request not found';
  end if;
  if r.status <> 'pending' then
    raise exception 'station request is already %', r.status;
  end if;

  if r.station_id is not null then
    update public.stations
       set broadcaster_org_id = coalesce(r.org_id, broadcaster_org_id),
           stream_url = coalesce(nullif(btrim(r.stream_url), ''), stream_url)
     where id = r.station_id
     returning id into new_id;
    if new_id is null then
      raise exception 'the station no longer exists';
    end if;
  else
    new_slug := btrim(lower(regexp_replace(coalesce(r.name, '') || ' ' || coalesce(r.frequency, ''), '[^a-zA-Z0-9]+', '-', 'g')), '-');
    insert into public.stations (name, slug, frequency, region, kind, stream_url, broadcaster_org_id, stream_status)
    values (
      btrim(r.name),
      new_slug,
      nullif(btrim(coalesce(r.frequency, '')), ''),
      nullif(btrim(coalesce(r.region, '')), ''),
      coalesce(r.kind, 'radio'),
      nullif(btrim(coalesce(r.stream_url, '')), ''),
      r.org_id,
      case when nullif(btrim(coalesce(r.stream_url, '')), '') is null then 'no_stream_url' else 'starting' end
    )
    on conflict (slug) do update
      set broadcaster_org_id = coalesce(excluded.broadcaster_org_id, public.stations.broadcaster_org_id),
          stream_url = coalesce(excluded.stream_url, public.stations.stream_url)
    returning id into new_id;
  end if;

  update public.station_requests
     set status = 'approved', reviewed_at = now(), reviewed_by = auth.uid()
   where id = p_id;

  return new_id;
end $$;

create or replace function public.reject_station_request(p_id uuid, p_note text default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.my_role() is distinct from 'cmo' then
    raise exception 'only a CMO can reject a station request';
  end if;
  update public.station_requests
     set status = 'rejected', review_note = nullif(btrim(coalesce(p_note, '')), ''),
         reviewed_at = now(), reviewed_by = auth.uid()
   where id = p_id and status = 'pending';
  if not found then
    raise exception 'no pending station request with that id';
  end if;
end $$;

revoke all on function public.approve_station_request(uuid) from public;
revoke all on function public.reject_station_request(uuid, text) from public;
grant execute on function public.approve_station_request(uuid) to authenticated;
grant execute on function public.reject_station_request(uuid, text) to authenticated;

-- ==========================================================================
-- 21. 0021_panel_stats.sql
-- Public stats report panel size as well as live streams
-- ==========================================================================

-- ── Panel size in the public stats ─────────────────────────────────────────
--
-- public_platform_stats() is deliberately strict about "monitoring": a station
-- only counts as live if its worker heartbeat is under ten minutes old (0009).
-- That is the right rule, but it left the header reading "0 Stations Monitored
-- Live" whenever the worker was between runs — true, and useless to a visitor
-- deciding whether to sign up.
--
-- So the same call now also reports two build-out facts that hold whether or
-- not a worker is running: how many stations are in the panel, and how many
-- have a stream URL we can read. The header shows the live figure when it
-- exists and the panel figure when it does not. Nothing here claims a play has
-- been heard; detections_24h still answers that, and it is still zero.

drop function if exists public.public_platform_stats();

create function public.public_platform_stats()
returns table (
  streams_online bigint,
  venues bigint,
  detections_24h bigint,
  panel_stations bigint,
  stream_ready bigint
)
language sql
stable
security definer
set search_path = public
as $$
  select (select count(*) from public.stations
           where stream_status = 'online'
             and last_heartbeat > now() - interval '10 minutes'),
         (select count(*) from public.venues),
         (select count(*) from public.detections
           where detected_at >= now() - interval '24 hours'),
         (select count(*) from public.stations
           where coalesce(stream_status, '') <> 'disabled'),
         (select count(*) from public.stations
           where coalesce(stream_status, '') <> 'disabled'
             and nullif(btrim(coalesce(stream_url, '')), '') is not null)
$$;

revoke execute on function public.public_platform_stats() from public;
grant execute on function public.public_platform_stats() to anon, authenticated;

-- The readiness board made the same mistake in a different place: it read
-- `monitored` (a settable status column) and reported "25 streaming" while no
-- worker was running. Expose the stream-URL count so the board can describe
-- the panel without implying anyone is listening.
create or replace function public.public_ingest_health()
returns json
language sql
stable
security definer
set search_path = public
as $$
  select json_build_object(
    'stations',       (select count(*) from public.stations),
    'monitored',      (select count(*) from public.stations
                        where stream_status in ('starting', 'online', 'reconnecting')),
    'stream_ready',   (select count(*) from public.stations
                        where nullif(btrim(coalesce(stream_url, '')), '') is not null),
    'last_heartbeat', (select max(last_heartbeat) from public.stations),
    'last_detection', (select max(detected_at) from public.detections)
  );
$$;

revoke all on function public.public_ingest_health() from public;
grant execute on function public.public_ingest_health() to anon, authenticated;

-- ==========================================================================
-- 22. 0022_recording_credits.sql
-- Many songwriters and featured artists per song
-- ==========================================================================

-- ── More than one songwriter, more than one feature ───────────────────────
--
-- `recordings.composer` and `recordings.featuring` were single text fields, so
-- a song with three writers had to be typed as one blob ("A, B & C") and a
-- cue sheet printed that blob as if it were a person's name. UPRS distributes
-- to people, so the writer list is not a display detail — it is the royalty
-- claim.
--
-- Credits now live in their own table: one row per person, with a role and an
-- order. The two old text columns are still written (joined with "; ") because
-- the worker, the cue-sheet generator, the broadcaster timeline and the CSV
-- exports all read them — that keeps this additive instead of a migration of
-- every consumer.

create table if not exists public.recording_credits (
  id uuid primary key default gen_random_uuid(),
  recording_id uuid not null references public.recordings (id) on delete cascade,
  role text not null check (role in ('songwriter', 'featured')),
  name text not null check (length(btrim(name)) > 0),
  -- Set when the person has an East Sound account, so a writer can later see
  -- their own credits. Null is normal: most writers are typed in by name.
  profile_id uuid references public.profiles (id) on delete set null,
  position int not null default 0,
  created_at timestamptz not null default now()
);

-- The same person cannot be credited twice in the same role on one song,
-- whatever the capitalisation ("Nalu" vs "nalu").
create unique index if not exists recording_credits_unique
  on public.recording_credits (recording_id, role, lower(btrim(name)));
create index if not exists recording_credits_recording
  on public.recording_credits (recording_id, role, position);

-- Who may edit credits: exactly who may edit the recording itself.
create or replace function public.owns_recording(p_recording uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
      from public.recordings r
     where r.id = p_recording
       and (
            (public.my_role() = 'label'  and r.label_org_id = public.my_org())
         or (public.my_role() = 'artist' and r.artist_profile_id = auth.uid() and r.label_org_id is null)
       )
  )
$$;
revoke all on function public.owns_recording(uuid) from public;
grant execute on function public.owns_recording(uuid) to authenticated;

alter table public.recording_credits enable row level security;

-- The owner, their label, the CMO — and a writer whose account is credited.
drop policy if exists recording_credits_read on public.recording_credits;
create policy recording_credits_read on public.recording_credits for select using (
  public.my_role() = 'cmo'
  or public.owns_recording(recording_id)
  or profile_id = auth.uid()
);

drop policy if exists recording_credits_write on public.recording_credits;
create policy recording_credits_write on public.recording_credits for insert
  with check (public.owns_recording(recording_id));

drop policy if exists recording_credits_update on public.recording_credits;
create policy recording_credits_update on public.recording_credits for update
  using (public.owns_recording(recording_id))
  with check (public.owns_recording(recording_id));

drop policy if exists recording_credits_delete on public.recording_credits;
create policy recording_credits_delete on public.recording_credits for delete
  using (public.owns_recording(recording_id));

-- ==========================================================================
-- 23. 0023_stream_errors.sql
-- Stations record why a stream cannot be read
-- ==========================================================================

-- ── Why a station is not being recorded ────────────────────────────────────
--
-- On 11 November every one of the 25 streaming stations sat at `reconnecting`
-- while the worker heartbeated happily. The reason existed only in the Railway
-- log tail ("Connection refused", "Server returned 403 Forbidden", …), which is
-- exactly nowhere when you are holding a phone. A panel that says "reconnecting"
-- forever is indistinguishable from a panel that is working.
--
-- So the worker now writes the last thing ffmpeg said. It is diagnostic text,
-- not content: no audio, no URLs of subscriber streams, just the sentence that
-- explains the silence.

alter table public.stations add column if not exists stream_error text;
alter table public.stations add column if not exists stream_error_at timestamptz;

comment on column public.stations.stream_error is
  'Last capture error reported by the worker (ffmpeg stderr, trimmed). Null while monitoring is healthy.';

-- The readiness board should be able to say "26 stations are configured and
-- none can be read, and here is the sentence that explains why" in one call.
create or replace function public.public_ingest_health()
returns json
language sql
stable
security definer
set search_path = public
as $$
  select json_build_object(
    'stations',       (select count(*) from public.stations),
    'monitored',      (select count(*) from public.stations
                        where stream_status in ('starting', 'online', 'reconnecting')),
    'stream_ready',   (select count(*) from public.stations
                        where nullif(btrim(coalesce(stream_url, '')), '') is not null),
    'stream_errors',  (select count(*) from public.stations
                        where stream_error is not null
                          and coalesce(stream_status, '') <> 'online'),
    'sample_error',   (select left(regexp_replace(stream_error, 'https?://\S+', '<stream>', 'gi'), 200)
                        from public.stations
                        where stream_error is not null
                        order by stream_error_at desc nulls last
                        limit 1),
    'last_heartbeat', (select max(last_heartbeat) from public.stations),
    'last_detection', (select max(detected_at) from public.detections)
  );
$$;

revoke all on function public.public_ingest_health() from public;
grant execute on function public.public_ingest_health() to anon, authenticated;

-- ==========================================================================
-- 24. 0024_worker_build.sql
-- Stations record which worker build heartbeated them
-- ==========================================================================

-- Which build is running?

alter table public.stations add column if not exists worker_build text;

comment on column public.stations.worker_build is
  'Commit the ingest worker was built from (Railway injects the SHA) at its last heartbeat. Answers "did my deploy actually land?" without opening the logs.';

create or replace function public.public_ingest_health()
returns json
language sql
stable
security definer
set search_path = public
as $$
  select json_build_object(
    'stations',       (select count(*) from public.stations),
    'monitored',      (select count(*) from public.stations
                        where stream_status in ('starting', 'online', 'reconnecting')),
    'stream_ready',   (select count(*) from public.stations
                        where nullif(btrim(coalesce(stream_url, '')), '') is not null),
    'stream_errors',  (select count(*) from public.stations
                        where stream_error is not null
                          and coalesce(stream_status, '') <> 'online'),
    'sample_error',   (select left(regexp_replace(stream_error, 'https?://\S+', '<stream>', 'gi'), 200)
                        from public.stations
                        where stream_error is not null
                        order by stream_error_at desc nulls last
                        limit 1),
    'worker_build',   (select worker_build from public.stations
                        where worker_build is not null
                        order by last_heartbeat desc nulls last
                        limit 1),
    'last_heartbeat', (select max(last_heartbeat) from public.stations),
    'last_detection', (select max(detected_at) from public.detections)
  );
$$;

revoke all on function public.public_ingest_health() from public;
grant execute on function public.public_ingest_health() to anon, authenticated;

-- ==========================================================================
-- 25. 0025_insights_and_proof.sql
-- Airplay insights for rights holders and shareable proof-of-play links
-- ==========================================================================

-- Airplay insights for rights holders, and shareable proof-of-play links.
--
-- 1. artist_airplay_insights(days): for the songs the caller owns (artist or
--    label, via owns_recording), which stations play them, which monitored
--    stations do not, what hours they are played, and the latest plays with
--    their evidence clip. Station names are returned only in that context;
--    the stations table itself stays closed to artists and labels.
-- 2. share_detection / unshare_detection: an owner can publish one play as a
--    link (/proof/<token>). proof_by_token returns that one play to anyone with
--    the token, and storage lets anyone read that one clip — nothing else.

alter table public.detections add column if not exists share_token text;
create unique index if not exists detections_share_token_key on public.detections (share_token) where share_token is not null;

create or replace function public.artist_airplay_insights(p_days integer default 30)
returns json
language sql
stable
security definer
set search_path = public
as $$
  with mine as (
    select d.id, d.station_id, d.detected_at, d.duration_sec, d.confidence, d.evidence_path, d.share_token, d.recording_id
      from detections d
     where d.recording_id is not null
       and d.detected_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 365)))
       and owns_recording(d.recording_id)
  )
  select json_build_object(
    'days', greatest(1, least(coalesce(p_days, 30), 365)),
    'plays', (select count(*) from mine),
    'stations_playing', (select count(distinct station_id) from mine),
    'stations_monitored', (select count(*) from stations where stream_status = 'online'),
    'by_station', coalesce((
      select json_agg(x order by x.plays desc, x.name)
        from (select s.name, s.region, count(*) as plays, max(m.detected_at) as last_play
                from mine m join stations s on s.id = m.station_id
               group by s.id, s.name, s.region) x), '[]'::json),
    'not_playing', coalesce((
      select json_agg(json_build_object('name', s.name, 'region', coalesce(s.region, 'Other')) order by s.region, s.name)
        from stations s
       where s.stream_status = 'online'
         and not exists (select 1 from mine m where m.station_id = s.id)), '[]'::json),
    'by_hour', (
      select json_agg(coalesce(z.c, 0) order by h)
        from generate_series(0, 23) h
        left join (select extract(hour from detected_at at time zone 'Africa/Kampala')::int as hr, count(*) as c
                     from mine group by 1) z on z.hr = h),
    'by_weekday', (
      select json_agg(coalesce(z.c, 0) order by dow)
        from generate_series(1, 7) dow
        left join (select extract(isodow from detected_at at time zone 'Africa/Kampala')::int as d, count(*) as c
                     from mine group by 1) z on z.d = dow),
    'recent', coalesce((
      select json_agg(x order by x.detected_at desc)
        from (select m.id, r.title, s.name as station, s.frequency, m.detected_at, m.duration_sec,
                     m.evidence_path, m.share_token
                from mine m
                join recordings r on r.id = m.recording_id
                left join stations s on s.id = m.station_id
               order by m.detected_at desc
               limit 20) x), '[]'::json)
  );
$$;
revoke all on function public.artist_airplay_insights(integer) from public, anon;
grant execute on function public.artist_airplay_insights(integer) to authenticated;

create or replace function public.share_detection(p_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rec uuid;
  v_token text;
begin
  select recording_id, share_token into v_rec, v_token from detections where id = p_id;
  if v_rec is null or not owns_recording(v_rec) then
    raise exception 'You can only share plays of your own songs.' using errcode = '42501';
  end if;
  if v_token is null then
    v_token := replace(gen_random_uuid()::text, '-', '');
    update detections set share_token = v_token where id = p_id;
  end if;
  return v_token;
end;
$$;
revoke all on function public.share_detection(bigint) from public, anon;
grant execute on function public.share_detection(bigint) to authenticated;

create or replace function public.unshare_detection(p_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rec uuid;
begin
  select recording_id into v_rec from detections where id = p_id;
  if v_rec is null or not owns_recording(v_rec) then
    raise exception 'You can only change plays of your own songs.' using errcode = '42501';
  end if;
  update detections set share_token = null where id = p_id;
end;
$$;
revoke all on function public.unshare_detection(bigint) from public, anon;
grant execute on function public.unshare_detection(bigint) to authenticated;

-- One shared play, for the public proof page. Tokens are 32 hex characters.
create or replace function public.proof_by_token(p_token text)
returns json
language sql
stable
security definer
set search_path = public
as $$
  select json_build_object(
    'title', r.title, 'artist', r.artist_name, 'featuring', r.featuring, 'isrc', r.isrc,
    'station', s.name, 'frequency', s.frequency, 'region', s.region,
    'detected_at', d.detected_at, 'duration_sec', d.duration_sec, 'confidence', d.confidence,
    'evidence_path', d.evidence_path)
    from detections d
    join recordings r on r.id = d.recording_id
    left join stations s on s.id = d.station_id
   where p_token ~ '^[0-9a-f]{32}$'
     and d.share_token = p_token
$$;
revoke all on function public.proof_by_token(text) from public;
grant execute on function public.proof_by_token(text) to anon, authenticated;

create or replace function public.is_shared_evidence(p_name text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from detections where evidence_path = p_name and share_token is not null)
$$;
revoke all on function public.is_shared_evidence(text) from public;
grant execute on function public.is_shared_evidence(text) to anon, authenticated;

drop policy if exists evidence_shared_read on storage.objects;
create policy evidence_shared_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'evidence' and public.is_shared_evidence(name));

-- ==========================================================================
-- 26. 0026_insights_artist_name.sql
-- Insights show which artist each play belongs to
-- ==========================================================================

-- Recent plays in artist_airplay_insights carry the artist name, so a label can
-- see which roster artist each play belongs to. Same function otherwise.

create or replace function public.artist_airplay_insights(p_days integer default 30)
returns json
language sql
stable
security definer
set search_path = public
as $$
  with mine as (
    select d.id, d.station_id, d.detected_at, d.duration_sec, d.confidence, d.evidence_path, d.share_token, d.recording_id
      from detections d
     where d.recording_id is not null
       and d.detected_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 365)))
       and owns_recording(d.recording_id)
  )
  select json_build_object(
    'days', greatest(1, least(coalesce(p_days, 30), 365)),
    'plays', (select count(*) from mine),
    'stations_playing', (select count(distinct station_id) from mine),
    'stations_monitored', (select count(*) from stations where stream_status = 'online'),
    'by_station', coalesce((
      select json_agg(x order by x.plays desc, x.name)
        from (select s.name, s.region, count(*) as plays, max(m.detected_at) as last_play
                from mine m join stations s on s.id = m.station_id
               group by s.id, s.name, s.region) x), '[]'::json),
    'not_playing', coalesce((
      select json_agg(json_build_object('name', s.name, 'region', coalesce(s.region, 'Other')) order by s.region, s.name)
        from stations s
       where s.stream_status = 'online'
         and not exists (select 1 from mine m where m.station_id = s.id)), '[]'::json),
    'by_hour', (
      select json_agg(coalesce(z.c, 0) order by h)
        from generate_series(0, 23) h
        left join (select extract(hour from detected_at at time zone 'Africa/Kampala')::int as hr, count(*) as c
                     from mine group by 1) z on z.hr = h),
    'by_weekday', (
      select json_agg(coalesce(z.c, 0) order by dow)
        from generate_series(1, 7) dow
        left join (select extract(isodow from detected_at at time zone 'Africa/Kampala')::int as d, count(*) as c
                     from mine group by 1) z on z.d = dow),
    'recent', coalesce((
      select json_agg(x order by x.detected_at desc)
        from (select m.id, r.title, r.artist_name as artist, s.name as station, s.frequency, m.detected_at, m.duration_sec,
                     m.evidence_path, m.share_token
                from mine m
                join recordings r on r.id = m.recording_id
                left join stations s on s.id = m.station_id
               order by m.detected_at desc
               limit 20) x), '[]'::json)
  );
$$;
revoke all on function public.artist_airplay_insights(integer) from public, anon;
grant execute on function public.artist_airplay_insights(integer) to authenticated;

-- ==========================================================================
-- 27. 0027_song_airplay_report.sql
-- Per-song airplay report keyed by ISRC
-- ==========================================================================

-- Per-song airplay report for rights holders, keyed by ISRC/UPC so a distributor
-- or label can match it to their own catalogue. Owner-scoped like
-- artist_airplay_insights: only songs the caller owns (owns_recording).

create or replace function public.song_airplay_report(p_days integer default 30)
returns json
language sql
stable
security definer
set search_path = public
as $$
  with span as (select greatest(1, least(coalesce(p_days, 30), 365)) as days),
  mine as (
    select r.id, r.title, r.artist_name, r.featuring, r.isrc, r.upc
      from recordings r
     where owns_recording(r.id)
  ),
  plays as (
    select d.recording_id, d.station_id, d.detected_at, d.share_token
      from detections d, span
     where d.recording_id in (select id from mine)
       and d.detected_at > now() - make_interval(days => span.days)
  )
  select json_build_object(
    'days', (select days from span),
    'songs', coalesce((
      select json_agg(x order by x.plays desc, x.title)
        from (
          select m.id, m.title, m.artist_name as artist, m.featuring, m.isrc, m.upc,
                 count(p.station_id) as plays,
                 count(distinct p.station_id) as stations,
                 min(p.detected_at) as first_play,
                 max(p.detected_at) as last_play,
                 coalesce((select json_agg(distinct s.region) from plays p2 join stations s on s.id = p2.station_id
                            where p2.recording_id = m.id and s.region is not null), '[]'::json) as regions,
                 coalesce((select json_agg(t) from (
                            select s.name, count(*) as plays
                              from plays p3 join stations s on s.id = p3.station_id
                             where p3.recording_id = m.id
                             group by s.name order by count(*) desc, s.name limit 3) t), '[]'::json) as top_stations,
                 (select p4.share_token from plays p4 where p4.recording_id = m.id and p4.share_token is not null
                   order by p4.detected_at desc limit 1) as proof_token
            from mine m
            left join plays p on p.recording_id = m.id
           group by m.id, m.title, m.artist_name, m.featuring, m.isrc, m.upc) x), '[]'::json)
  );
$$;
revoke all on function public.song_airplay_report(integer) from public, anon;
grant execute on function public.song_airplay_report(integer) to authenticated;

commit;
